// gf3_field.h — 层1: GF(3) 有限域, 3≡0, 每trit独立
//
// 宪法声明:
//   几何本源: 正四面体 C3 轴 (120°旋转) → {不动, +1步, +2步} = {T₀,T₁,T₂}
//   范畴: GF(3) = Z/3Z, 特征3, 3=0
//
// v2.0 实测: GF(3)三态在超流体中形成C3孤子循环
//   本征值{94.8,4.3,0.9}在1500步周期上严格轮转
//   trit=2(干涉调制)在固相冻结, 居里相变后激活
//   驻波节点(tone%3==0)是泛音共振的自然吸引子
//   运算: C3旋转编码 — c3_cw (顺时针), c3_ccw (逆时针)
//         GF(3)乘法 — 仅用于编码/解码, 不是几何操作
//
//   禁止从实数域借来的概念: 减法、除法、逆元、"负数"
//   T₂不是T₁的"逆元" — T₂是顺转两步, 不是"往回走一步"
//
//   范畴边界: GF(3) ≠ Z/3¹¹Z
//   GF(3): 每trit独立, 3=0, 无位权
//   Z/3¹¹Z: 位权3^k, 3≠0, 进位传播
#ifndef SOV_MATH_GF3_FIELD_H
#define SOV_MATH_GF3_FIELD_H

#include "gf3_types.h"
#include <cstdint>

namespace sov::math::gf3 {

// ═══════════════════════════════════════════════════════════════════════
// 一、GF(3) 元素 — 来自几何, 不是来自代数
// ═══════════════════════════════════════════════════════════════════════

// [层1] [GF(3)] 三个元素: 正四面体 C3 轴的三个旋转态
//   T₀ = 0 → 不动 (旋转0°)
//   T₁ = 1 → 顺时针旋转 120°
//   T₂ = 2 → 顺时针旋转 240° = 顺转两步
inline constexpr uint8_t T0 = 0;
inline constexpr uint8_t T1 = 1;
inline constexpr uint8_t T2 = 2;

// ═══════════════════════════════════════════════════════════════════════
// 二、C3 旋转操作 — 这是 GF(3) 上的唯一原生操作
// ═══════════════════════════════════════════════════════════════════════

// [层1] [几何→代数] C3 顺时针: 旋转 +120°
//   T₀ → T₁ → T₂ → T₀ → ...
[[nodiscard]] constexpr uint8_t c3_cw(uint8_t t) noexcept {
    return (t + 1) % 3;
}

// [层1] [几何→代数] C3 逆时针: 旋转 +240° = +2步 = 逆时针120°
//   不是"减法" — 是两个正向步
[[nodiscard]] constexpr uint8_t c3_ccw(uint8_t t) noexcept {
    return (t + 2) % 3;
}

// [层1] [几何→代数] C3 验证: 三步回到自身 (3×120° = 360°)
static_assert(c3_cw(c3_cw(c3_cw(T0))) == T0, "C3: 3×CW=T0");
static_assert(c3_ccw(c3_ccw(c3_ccw(T0))) == T0, "C3: 3×CCW=T0");
// CW∘CCW = 恒等 (两个方向互为逆)
static_assert(c3_cw(c3_ccw(T1)) == T1, "C3: CW∘CCW=id");

// ═══════════════════════════════════════════════════════════════════════
// 三、GF(3) 乘法 — 编码运算, 非几何
// ═══════════════════════════════════════════════════════════════════════

// [层1] [GF(3)] 乘法: (a×b)%3, 仅用于打包/解包
//   2×2=4≡1 — 顺转两步再做两次 = 回到T₁
[[nodiscard]] constexpr uint8_t mul(uint8_t a, uint8_t b) noexcept {
    return TRIT_MUL_LUT[a][b];
}

// ═══════════════════════════════════════════════════════════════════════
// 四、GF(3) 范数 — 几何距离
// ═══════════════════════════════════════════════════════════════════════

// [层1] [GF(3)] 范数平方: 不动→0, 旋转→1
//   |T₀|² = 0 (不动点)
//   |T₁|² = 1 (120°旋转)
//   |T₂|² = 1 (240°旋转, 2²=4≡1)
[[nodiscard]] constexpr uint8_t norm_sq(uint8_t t) noexcept {
    return TRIT_NORM_LUT[t];
}

// ═══════════════════════════════════════════════════════════════════════
// 五、GF(3) 特征: 1+1+1=0
// ═══════════════════════════════════════════════════════════════════════

// [层1] [GF(3)] C3旋转: 三步回到自身 (不是回到T0 — 那是加法特征)
//   T1→T2→T0→T1: 三次CW回到自身
//   GF(3)加法特征: 1+1+1=3≡0 (三次加法归零, 非旋转)
static_assert(c3_cw(c3_cw(c3_cw(T1))) == T1, "C3: CW³=id");
static_assert(c3_cw(c3_cw(c3_cw(T2))) == T2, "C3: CW³=id");
// GF(3)特征3: 1+1+1 ≡ 0 mod 3 (代数归零, 非几何操作)

// ═══════════════════════════════════════════════════════════════════════
// 范畴边界: GF(3) 到此为止
// 以下概念属于 Z/3¹¹Z 环 (z3r_ring.h), 不属于 GF(3):
//   - 位权 3^k (T1=3¹, T2=3² 的定义在 Z/3¹¹Z)
//   - 逢三进一进位传播
//   - 基3位置记数
//   - RingElement 类型
// 以下概念属于几何 (chiral_geometry.h), 不属于 GF(3):
//   - 手征共轭 ω↔ω²
//   - 手性离合器
//   - 五行振幅
// ═══════════════════════════════════════════════════════════════════════

} // namespace sov::math::gf3

#endif // SOV_MATH_GF3_FIELD_H
